const patchedContent = `/* !!! This is code generated by Prisma. Do not edit directly. !!! */
/* eslint-disable */
// biome-ignore-all lint: generated file
import queryCompilerWasm from './query_compiler_fast_bg.wasm?module';
export default Promise.resolve({ default: queryCompilerWasm });
`;

if (fs.existsSync(targetFile)) {
  fs.writeFileSync(targetFile, patchedContent, 'utf8');
  console.log('Successfully patched wasm-worker-loader.mjs for Cloudflare Workers static Wasm import');
} else {
  console.error('Target file wasm-worker-loader.mjs not found');
}
